WITH invoices(id,supplier_id,face) AS (
 SELECT 1,1,10000 UNION ALL SELECT 2,1,5000 UNION ALL SELECT 3,2,8000 UNION ALL SELECT 4,2,4000 UNION ALL SELECT 5,3,3000
), credits(id,credit_date,approved,amount) AS (
 SELECT 1,'2025-12-01',1,2000 UNION ALL SELECT 5,'2025-12-01',1,3000
 UNION ALL SELECT 2,'2025-12-01',0,1000
), payments(id,payment_date,amount) AS (
 SELECT 1,'2025-12-01',3000 UNION ALL SELECT 1,'2025-12-20',2000
 UNION ALL SELECT 1,'2026-01-01',3000 UNION ALL SELECT 3,'2025-12-01',8000
 UNION ALL SELECT 4,'2025-12-01',4500
), c AS (SELECT id,SUM(amount) credit FROM credits WHERE approved=1 AND credit_date<='2025-12-31' GROUP BY id), p AS (SELECT id,SUM(amount) paid FROM payments WHERE payment_date<='2025-12-31' GROUP BY id), v_invoice_balance AS (
 SELECT i.id supplier_invoice_id,i.supplier_id,i.face-COALESCE(c.credit,0) billed_cents,COALESCE(p.paid,0) paid_cents,i.face-COALESCE(c.credit,0)-COALESCE(p.paid,0) balance_cents FROM invoices i LEFT JOIN c ON c.id=i.id LEFT JOIN p ON p.id=i.id
) SELECT id,credit FROM c ORDER BY credit DESC

